// packages/renderer/src/api/domains/chat.ts
export function send(sessionId, text, images?) {
  // images 为 undefined 时不传 images 键（runtime rpc-client 已守卫 images.length>0，rpc-client.ts:430）
  return command('message.send', images ? { sessionId, content: text, images } : { sessionId, content: text })
}
// images 形状对齐 shared protocol message.send（protocol.ts:199）：{ data: base64不含data:前缀; mimeType }
// consumer: useChat.send（唯一调用方）

